FUNCTION_BLOCK FB
VAR_INPUT
    tankLevel    : REAL;
    outletFlow   : REAL;
    inletPermit  : BOOL;
    resetBtn     : BOOL;
END_VAR
VAR_OUTPUT
    pumpRun         : BOOL;
    alarmHigh       : BOOL;
    alarmLow        : BOOL;
    outletValveOpen : BOOL;
END_VAR
VAR
    prevResetBtn    : BOOL;
    risingResetEdge : BOOL;
END_VAR

risingResetEdge := resetBtn AND NOT prevResetBtn;
prevResetBtn := resetBtn;

IF tankLevel >= 85.0 THEN
    alarmHigh := TRUE;
END_IF

IF tankLevel <= 15.0 THEN
    alarmLow := TRUE;
END_IF

IF risingResetEdge THEN
    IF tankLevel < 85.0 AND alarmHigh THEN
        alarmHigh := FALSE;
    END_IF
    IF tankLevel > 15.0 AND alarmLow THEN
        alarmLow := FALSE;
    END_IF
END_IF

IF alarmHigh THEN
    pumpRun := FALSE;
ELSIF inletPermit AND tankLevel > 15.0 AND tankLevel < 85.0 THEN
    pumpRun := TRUE;
ELSE
    pumpRun := FALSE;
END_IF

IF alarmLow THEN
    outletValveOpen := FALSE;
ELSIF tankLevel > 15.0 THEN
    outletValveOpen := TRUE;
ELSE
    outletValveOpen := FALSE;
END_IF

END_FUNCTION_BLOCK
